cssVarsTemplate:
@tailwind base;
@tailwind components;
@tailwind utilities;

@layer base {
  :root {
    --background: 0 0% 100%;
    --foreground: 220 29% 5%;
    --card: 0 0% 100%;
    --card-foreground: 220 29% 5%;
    --popover: 0 0% 100%;
    --popover-foreground: 220 29% 5%;
    --primary: 220 23% 12%;
    --primary-foreground: 0 0% 98%;
    --secondary: 0 0% 96%;
    --secondary-foreground: 220 23% 12%;
    --muted: 0 0% 96%;
    --muted-foreground: 220 8% 47%;
    --accent: 0 0% 96%;
    --accent-foreground: 220 23% 12%;
    --destructive: 10 85% 58%;
    --destructive-foreground: 0 0% 98%;
    --border: 210 6% 92%;
    --input: 210 6% 92%;
    --ring: 220 29% 5%;
    --radius: 0.5rem;
    --chart-1: 12 76% 61%;
    --chart-2: 173 58% 39%;
    --chart-3: 197 37% 24%;
    --chart-4: 43 74% 66%;
    --chart-5: 27 87% 67%;
  }

  .dark {
    --background: 220 29% 5%;
    --foreground: 0 0% 98%;
    --card: 220 29% 5%;
    --card-foreground: 0 0% 98%;
    --popover: 220 29% 5%;
    --popover-foreground: 0 0% 98%;
    --primary: 0 0% 98%;
    --primary-foreground: 220 23% 12%;
    --secondary: 220 19% 18%;
    --secondary-foreground: 0 0% 98%;
    --muted: 220 19% 18%;
    --muted-foreground: 220 7% 66%;
    --accent: 220 19% 18%;
    --accent-foreground: 0 0% 98%;
    --destructive: 10 63% 29%;
    --destructive-foreground: 0 0% 98%;
    --border: 220 19% 18%;
    --input: 220 19% 18%;
    --ring: 220 6% 85%;
    --chart-1: 220 70% 50%;
    --chart-2: 160 60% 45%;
    --chart-3: 30 80% 55%;
    --chart-4: 280 65% 60%;
    --chart-5: 340 75% 55%;
  }
}

@layer base {
  * {
    @apply border-border;
  }
  body {
    @apply bg-background text-foreground;
  }
}
